"""Робот edu 13.11 (восемнадцатый запуск). Карточки организаций отобранных кандидатов (ключи ev<n>-1128e) → auto/fetch-queue.txt."""
import json, os, re, urllib.parse
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
K = json.load(open(os.path.join(ROOT, "tools/edu_1128_keep.json")))
TAKE = set([1, 3, 6, 7, 9, 10, 11, 15, 16, 17, 18, 19, 21, 23, 24, 25, 27, 28, 29, 33, 35, 37, 40, 41, 42, 44, 45, 47, 51, 52, 53, 54, 60, 61, 62, 63, 64, 65, 67, 68, 72, 73, 74, 75, 78, 80, 82, 83, 84, 85, 86, 87, 88, 90, 91, 92, 95, 101, 102, 103, 104, 105, 106, 108, 109, 112, 113, 114, 116, 117, 119, 123, 124, 125, 126, 128, 129, 132, 135, 136, 137, 139, 141, 142, 143, 144, 145, 147, 148, 149, 150, 151, 153, 155, 156, 161, 163, 165, 166, 167, 169, 171, 172, 173, 174, 175, 176, 177, 179, 180, 181, 182, 183, 185, 186, 187, 188, 189, 190, 192, 194, 195, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 211, 212, 213, 214, 218, 219, 220, 221, 222, 224, 225, 230, 232, 245, 248, 252, 258, 260, 262, 263, 266])
def short(a):
    return re.split(r", (Метро|метро|этаж|подъезд|вход|Вход|офис|кабинет|в помещ|домофон|жилой|ЖК|Отдельный|Пройдите)", a)[0]
urls = [f"https://yandex.ru/maps/1/moscow-and-moscow-oblast/?ev{c['n']}=1128e&text=" + urllib.parse.quote(f'{c["name"]}, {short(c["addr"])}')
        for c in K if c["n"] in TAKE]
if __name__ == "__main__":
    old = open(os.path.join(ROOT, "auto/fetch-queue.txt")).read()
    open(os.path.join(ROOT, "auto/fetch-queue.txt"), "w").write("\n".join(urls) + "\n" + old)
    print(len(urls))
